insert into public.cards (id, theme, kind, person, source_work, quote, color, sort_order, exa_queries, notes) values
('call-a-friend', 'FOCUS', 'action', null, null, 'Today is day to: Call your friend. Having social relationships can make us happy.', '#6fcab5', 1, array['social relationships happiness research longitudinal study', 'Harvard Study of Adult Development relationships happiness findings', 'calling a friend wellbeing loneliness study'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('plan-your-time', 'FOCUS', 'action', null, null, 'Today is day to: Plan your time. With an ever-hectic schedule, sometimes it''s easy to forget to schedule something else that''s crucial to your well-being: time off.', '#6fcab5', 2, array['scheduling leisure time off wellbeing research', 'time affluence happiness study', 'planning breaks rest productivity burnout research'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('be-a-hugger', 'FOCUS', 'action', null, null, 'Today is day to: Be a hugger today. The average hug lasts 2.1 seconds but for the endorphins to transfer it needs to last seven seconds or longer.', '#6fcab5', 3, array['hug duration study average hug 3 seconds', 'hugging oxytocin stress reduction research', '"seven seconds" hug endorphins claim evidence'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('take-the-stairs', 'FOCUS', 'action', null, null, 'Today is day to: Take the stairs. Taking the stairs can release endorphins that boost your mood and reduce stress, leading to increased happiness.', '#6fcab5', 4, array['randomized trial stair climbing mood cognitive performance young adults', 'stair climbing energy compared with caffeine study University of Georgia', 'short bouts stair climbing exercise snacks fitness study'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('use-names', 'FOCUS', 'action', null, null, 'Today is day to: Use everybody''s name. Always use person name before talking or making point - it is the best compliment for people.', '#6fcab5', 5, array['hearing own name brain activation study', 'Dale Carnegie name is the sweetest sound meaning', 'remembering names rapport sales communication research'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('less-social-media', 'FOCUS', 'action', null, null, 'Today is day to: Have less social media. Spend less time on electronic friends and more time with real flesh and blood ones.', '#6fcab5', 6, array['limiting social media use wellbeing randomized trial University of Pennsylvania', 'social media reduction loneliness depression study', 'face to face interaction versus online happiness research'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('smile', 'FOCUS', 'action', null, null, 'Today is day to: Smile! We smile because we''re happy, and smiling causes the brain to release dopamine, which makes us happier.', '#6fcab5', 7, array['smiling facial feedback hypothesis replication study', 'smiling dopamine serotonin mood evidence', 'Many Smiles Collaboration facial feedback results'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('be-grateful', 'FOCUS', 'action', null, null, 'Today is day to: Be grateful. You might try starting each day by acknowledging one thing you''re grateful for. You can do this while you''re brushing your teeth or just waiting for that snoozed alarm to go off.', '#6fcab5', 8, array['gratitude journaling wellbeing Emmons McCullough study', 'gratitude practice happiness randomized trial', 'morning gratitude habit research'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('give-a-compliment', 'FOCUS', 'action', null, null, 'Today is day to: Give a compliment. Giving a sincere compliment is a quick, easy way to brighten someone''s day while giving your own happiness a boost.', '#6fcab5', 9, array['giving compliments underestimate positive impact study Boothby Bohns', 'kindness acts happiness research', 'compliments wellbeing giver receiver study'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('plan-your-day', 'FOCUS', 'action', null, null, 'Today is day to: Plan your day. Sit down at the end of the day and make a basic list for the following day.', '#6fcab5', 10, array['writing to-do list before bed sleep study Scullin', 'implementation intentions planning goal achievement research', 'planning next day productivity evidence'], 'Check whether the claim on the card is supported by research; correct it gently if it is oversimplified.'),
('andy-rooney', 'LEGENDS', 'person', 'Andy Rooney', null, 'Everyone wants to live on top of the mountain, but all the happiness and growth occurs while you’re climbing it.', '#8ccbec', 11, array['"Everyone wants to live on top of the" Andy Rooney quote source', 'Andy Rooney interview on happiness and success', 'Andy Rooney life story biography key turning points', 'Andy Rooney advice for young people'], 'Widely shared as an Andy Rooney quote; check whether he actually said or wrote it, or whether it is misattributed.'),
('oprah-winfrey', 'LEGENDS', 'person', 'Oprah Winfrey', null, 'You are responsible for your life. You can’t keep blaming somebody else for your dysfunction. Life is really about moving on!', '#8ccbec', 12, array['"You are responsible for your life. You can’t" Oprah Winfrey quote source', 'Oprah Winfrey interview on happiness and success', 'Oprah Winfrey life story biography key turning points', 'Oprah Winfrey advice for young people'], null),
('mahatma-gandhi', 'LEGENDS', 'person', 'Mahatma Gandhi', null, 'Happiness is when what you think, what you say, and what you do are in harmony.', '#8ccbec', 13, array['"Happiness is when what you think, what you" Mahatma Gandhi quote source', 'Mahatma Gandhi interview on happiness and success', 'Mahatma Gandhi life story biography key turning points', 'Mahatma Gandhi advice for young people'], 'Very popular Gandhi attribution; look for a primary source in his writings or note if it is unverified.'),
('viktor-frankl', 'LEGENDS', 'person', 'Viktor Frankl', null, 'View your life from your funeral, looking back at your life experiences, what have you accomplished? What would you have wanted to accomplish but didn’t? What were the happy moments? What were the sad? What would you do again, and what you wouldn’t?', '#8ccbec', 14, array['"View your life from your funeral, looking back" Viktor Frankl quote source', 'Viktor Frankl interview on happiness and success', 'Viktor Frankl life story biography key turning points', 'Viktor Frankl advice for young people'], 'Check whether this exercise appears in Frankl''s works (e.g. Man''s Search for Meaning) or is a paraphrase/misattribution.'),
('dalai-lama', 'LEGENDS', 'person', 'Dalai Lama', null, 'Happiness is not something ready made. It comes from your own actions.', '#8ccbec', 15, array['"Happiness is not something ready made. It comes" Dalai Lama quote source', 'Dalai Lama interview on happiness and success', 'Dalai Lama life story biography key turning points', 'Dalai Lama advice for young people'], null),
('mark-manson', 'LEGENDS', 'person', 'Mark Manson', '"The Subtle Art of Not Giving a F*ck"', 'Happiness is like being cool - the harder you try the less it''s going to happen. So stop trying. Start living.', '#8ccbec', 16, array['"Happiness is like being cool - the harder" Mark Manson quote source', 'Mark Manson interview on happiness and success', 'Mark Manson life story biography key turning points', 'Mark Manson advice for young people'], null),
('richard-branson', 'LEGENDS', 'person', 'Richard Branson', '"Losing My Virginity"', 'Most people would assume my business success, and the wealth that comes with it, have brought me happiness. But I know I am successful, wealthy, and connected because I am happy.', '#8ccbec', 17, array['"Most people would assume my business success, and" Richard Branson quote source', 'Richard Branson interview on happiness and success', 'Richard Branson life story biography key turning points', 'Richard Branson advice for young people'], 'Check exact source (blog, book or interview).'),
('zig-ziglar', 'LEGENDS', 'person', 'Zig Ziglar', null, 'Happiness is not a destination, it''s a journey. Happiness is not tomorrow, it is now. Happiness is what you are, not what you have.', '#8ccbec', 18, array['"Happiness is not a destination, it''s a journey." Zig Ziglar quote source', 'Zig Ziglar interview on happiness and success', 'Zig Ziglar life story biography key turning points', 'Zig Ziglar advice for young people'], 'Check source; similar lines are attributed to several speakers.'),
('denis-waitley', 'LEGENDS', 'person', 'Denis Waitley', null, 'The biggest challenge in the world is to be yourself... and to be happy with that. Happiness is the ultimate success.', '#8ccbec', 19, array['"The biggest challenge in the world is to" Denis Waitley quote source', 'Denis Waitley interview on happiness and success', 'Denis Waitley life story biography key turning points', 'Denis Waitley advice for young people'], null),
('james-clear', 'LEGENDS', 'person', 'James Clear', '"Atomic Habits"', 'Happiness is simply the ability to not want more; to find gratitude and satisfaction in the moment that you have right now.', '#8ccbec', 20, array['"Happiness is simply the ability to not want" James Clear quote source', 'James Clear interview on happiness and success', 'James Clear life story biography key turning points', 'James Clear advice for young people'], 'Check whether James Clear actually wrote this (his site/newsletter) or it is misattributed.'),
('jordan-peterson', 'LEGENDS', 'person', 'Jordan Peterson', '"12 Rules for Life"', 'We are not happy, technically speaking, unless we see ourselves progressing - and the very idea of progression implies value.', '#8ccbec', 21, array['"We are not happy, technically speaking, unless we" Jordan Peterson quote source', 'Jordan Peterson interview on happiness and success', 'Jordan Peterson life story biography key turning points', 'Jordan Peterson advice for young people'], null),
('jordan-belfort', 'LEGENDS', 'person', 'Jordan Belfort', '"Way of the Wolf: Straight Line Selling"', 'Whether you say, ''I can'' or ''I can''t,'' you''re right either way.', '#8ccbec', 22, array['"Whether you say, ''I can'' or ''I can''t,''" Jordan Belfort quote source', 'Jordan Belfort interview on happiness and success', 'Jordan Belfort life story biography key turning points', 'Jordan Belfort advice for young people'], 'This line is classically attributed to Henry Ford (itself not firmly sourced). Check whether Belfort used it; if not, the card''s attribution is wrong — explain honestly and connect it to Belfort''s own ideas on belief and selling.'),
('steve-jobs', 'LEGENDS', 'person', 'Steve Jobs', null, 'If today were the last day of my life, would I want to do what I''m about to do today?', '#8ccbec', 23, array['"If today were the last day of my" Steve Jobs quote source', 'Steve Jobs interview on happiness and success', 'Steve Jobs life story biography key turning points', 'Steve Jobs advice for young people'], 'Source: Stanford commencement address, June 12, 2005.'),
('leonardo-dicaprio', 'ACTORS', 'person', 'Leonardo DiCaprio', null, 'If you can do what you do best and be happy, you''re further along in life than most people.', '#f7a35c', 24, array['"If you can do what you do best" Leonardo DiCaprio quote source', 'Leonardo DiCaprio interview on happiness and success', 'Leonardo DiCaprio life story biography key turning points', 'Leonardo DiCaprio advice for young people'], null),
('meryl-streep', 'ACTORS', 'person', 'Meryl Streep', null, 'The formula of happiness and success is just, being actually yourself, in the most vivid possible way you can.', '#f7a35c', 25, array['"The formula of happiness and success is just," Meryl Streep quote source', 'Meryl Streep interview on happiness and success', 'Meryl Streep life story biography key turning points', 'Meryl Streep advice for young people'], null),
('johnny-depp', 'ACTORS', 'person', 'Johnny Depp', null, 'Money doesn''t buy you happiness, but it buys you a big enough yacht to sail right up to it.', '#f7a35c', 26, array['"Money doesn''t buy you happiness, but it buys" Johnny Depp quote source', 'Johnny Depp interview on happiness and success', 'Johnny Depp life story biography key turning points', 'Johnny Depp advice for young people'], 'Often attributed to Depp about buying a private island; a very similar line is attributed to David Lee Roth. Do not discuss his court cases or relationships.'),
('will-smith', 'ACTORS', 'person', 'Will Smith', null, 'I wake up every morning believing today is going to be better than yesterday.', '#f7a35c', 27, array['"I wake up every morning believing today is" Will Smith quote source', 'Will Smith interview on happiness and success', 'Will Smith life story biography key turning points', 'Will Smith advice for young people'], null),
('jared-leto', 'ACTORS', 'person', 'Jared Leto', null, 'Happiness is like the weather. Sometimes it''s rainy, sometimes it''s sunny, and you gotta just go through and accept what''s there in front of you.', '#f7a35c', 28, array['"Happiness is like the weather. Sometimes it''s rainy," Jared Leto quote source', 'Jared Leto interview on happiness and success', 'Jared Leto life story biography key turning points', 'Jared Leto advice for young people'], null),
('robert-de-niro', 'ACTORS', 'person', 'Robert De Niro', null, 'Time goes on. So whatever you''re going to do, do it. Do it now. Don''t wait.', '#f7a35c', 29, array['"Time goes on. So whatever you''re going to" Robert De Niro quote source', 'Robert De Niro interview on happiness and success', 'Robert De Niro life story biography key turning points', 'Robert De Niro advice for young people'], null),
('jennifer-aniston', 'ACTORS', 'person', 'Jennifer Aniston', null, 'If you''re not happy, you can become happy. Happiness is a choice.', '#f7a35c', 30, array['"If you''re not happy, you can become happy." Jennifer Aniston quote source', 'Jennifer Aniston interview on happiness and success', 'Jennifer Aniston life story biography key turning points', 'Jennifer Aniston advice for young people'], null),
('hugh-jackman', 'ACTORS', 'person', 'Hugh Jackman', null, 'In life you don''t regret the things you do, you regret the things you don''t do.', '#f7a35c', 31, array['"In life you don''t regret the things you" Hugh Jackman quote source', 'Hugh Jackman interview on happiness and success', 'Hugh Jackman life story biography key turning points', 'Hugh Jackman advice for young people'], 'Similar lines are attributed to Lucille Ball and others; check whether Jackman said it.'),
('keanu-reeves', 'ACTORS', 'person', 'Keanu Reeves', null, 'You have to change your life if you’re not happy, and wake up if things aren’t going the way you want.', '#f7a35c', 32, array['"You have to change your life if you’re" Keanu Reeves quote source', 'Keanu Reeves interview on happiness and success', 'Keanu Reeves life story biography key turning points', 'Keanu Reeves advice for young people'], null),
('anthony-hopkins', 'ACTORS', 'person', 'Anthony Hopkins', null, 'There is no shortcut to happiness, you have to live your life.', '#f7a35c', 33, array['"There is no shortcut to happiness, you have" Anthony Hopkins quote source', 'Anthony Hopkins interview on happiness and success', 'Anthony Hopkins life story biography key turning points', 'Anthony Hopkins advice for young people'], null),
('beyonce', 'SINGERS', 'person', 'Beyoncé', null, 'Happiness comes from you. No one else can make you happy. You make you happy.', '#c49ac0', 34, array['"Happiness comes from you. No one else can" Beyoncé quote source', 'Beyoncé interview on happiness and success', 'Beyoncé life story biography key turning points', 'Beyoncé advice for young people'], 'Said in her 2014 video ''Yours and Mine''.'),
('wiz-khalifa', 'SINGERS', 'person', 'Wiz Khalifa', null, 'You don''t need too many people to be happy; just a few real ones who appreciate you for who you are.', '#c49ac0', 35, array['"You don''t need too many people to be" Wiz Khalifa quote source', 'Wiz Khalifa interview on happiness and success', 'Wiz Khalifa life story biography key turning points', 'Wiz Khalifa advice for young people'], null),
('harry-styles', 'SINGERS', 'person', 'Harry Styles', null, 'If you''re happy doing what you love, nobody can tell you that you''re not successful.', '#c49ac0', 36, array['"If you''re happy doing what you love, nobody" Harry Styles quote source', 'Harry Styles interview on happiness and success', 'Harry Styles life story biography key turning points', 'Harry Styles advice for young people'], null),
('chris-martin', 'SINGERS', 'person', 'Chris Martin', 'Coldplay', 'Life is beautiful in all it''s colors, even the darker ones, they''re here for a reason.', '#c49ac0', 37, array['"Life is beautiful in all it''s colors, even" Chris Martin quote source', 'Chris Martin interview on happiness and success', 'Chris Martin life story biography key turning points', 'Chris Martin advice for young people'], 'Attribution uncertain; check source.'),
('adam-levine', 'SINGERS', 'person', 'Adam Levine', 'Maroon 5', 'It''s much more interesting to embrace who you really are rather than waste energy pretending to be someone else.', '#c49ac0', 38, array['"It''s much more interesting to embrace who you" Adam Levine quote source', 'Adam Levine interview on happiness and success', 'Adam Levine life story biography key turning points', 'Adam Levine advice for young people'], null),
('katy-perry', 'SINGERS', 'person', 'Katy Perry', null, 'I''m happy, I''m in a good place, I''m looking forward to my future.', '#c49ac0', 39, array['"I''m happy, I''m in a good place, I''m" Katy Perry quote source', 'Katy Perry interview on happiness and success', 'Katy Perry life story biography key turning points', 'Katy Perry advice for young people'], null),
('mika', 'SINGERS', 'person', 'Mika', null, 'I make mistakes. I say stupid things. I do idiotic things. And, quite frankly, I''m proud of them. Why not make mistakes?', '#c49ac0', 40, array['"I make mistakes. I say stupid things. I" Mika quote source', 'Mika interview on happiness and success', 'Mika life story biography key turning points', 'Mika advice for young people'], null),
('lizzo', 'SINGERS', 'person', 'Lizzo', null, 'If I''m shinin'', everybody gonna shine. I was born like this, don''t even gotta try.', '#c49ac0', 41, array['"If I''m shinin'', everybody gonna shine. I was" Lizzo quote source', 'Lizzo interview on happiness and success', 'Lizzo life story biography key turning points', 'Lizzo advice for young people'], 'These appear to be song lyrics (likely from ''Juice'', 2019) — verify. The coach must never quote more lyrics than the card text.'),
('ryan-tedder', 'SINGERS', 'person', 'Ryan Tedder', 'OneRepublic', 'I have a theory that you can decide to make whatever day it is a good day.', '#c49ac0', 42, array['"I have a theory that you can decide" Ryan Tedder quote source', 'Ryan Tedder interview on happiness and success', 'Ryan Tedder life story biography key turning points', 'Ryan Tedder advice for young people'], null),
('madonna', 'SINGERS', 'person', 'Madonna', null, 'Happiness lies in your hand.', '#c49ac0', 43, array['"Happiness lies in your hand." Madonna quote source', 'Madonna interview on happiness and success', 'Madonna life story biography key turning points', 'Madonna advice for young people'], null),
('forrest-gump', 'MOVIES', 'character', 'Forrest Gump', 'Forrest Gump (1994)', 'Life is like a box of chocolates. You never know what you are gonna get.', '#f2d633', 44, array['"Life is like a box of chocolates. You" Forrest Gump Forrest Gump (1994)', 'Forrest Gump (1994) Forrest Gump character analysis', 'Forrest Gump (1994) behind the scenes making of', '"Life is like a box of chocolates. You" quote origin'], 'In the film Forrest quotes his mother in past tense (''life was like a box of chocolates'').'),
('rocky', 'MOVIES', 'character', 'Rocky Balboa', 'Rocky Balboa (2006)', 'It ain’t how hard you can hit. It’s how hard you can get hit and keep moving forward. It’s how much you can take, and keep moving forward. That’s how winning is done.', '#f2d633', 45, array['"It ain’t how hard you can hit. It’s" Rocky Balboa Rocky Balboa (2006)', 'Rocky Balboa (2006) Rocky Balboa character analysis', 'Rocky Balboa (2006) behind the scenes making of', '"It ain’t how hard you can hit. It’s" quote origin'], 'The card says ''Rocky''; the speech is from the film Rocky Balboa (2006) — verify.'),
('walt-disney', 'MOVIES', 'person', 'Walt Disney', 'Snow White and the Seven Dwarfs', 'The way to get started is to quit talking and begin doing.', '#f2d633', 46, array['"The way to get started is to quit" Walt Disney quote source', 'Walt Disney interview on happiness and success', 'Walt Disney life story biography key turning points', 'Walt Disney advice for young people'], 'This is attributed to Walt Disney the person, not a line from the film; check the real source.'),
('august-walker', 'MOVIES', 'character', 'August Walker', 'Mission: Impossible – Fallout (2018)', 'Hope is not a strategy.', '#f2d633', 47, array['"Hope is not a strategy." August Walker Mission: Impossible – Fallout (2018)', 'Mission: Impossible – Fallout (2018) August Walker character analysis', 'Mission: Impossible – Fallout (2018) behind the scenes making of', '"Hope is not a strategy." quote origin'], 'Verify the line is in the film and who says it.'),
('chris-gardner', 'MOVIES', 'character', 'Chris Gardner', 'The Pursuit of Happyness (2006)', 'Don’t ever let somebody tell you you can’t do something, not even me. Alright? You dream, you gotta protect it. People can’t do something themselves, they wanna tell you - you can’t do it. If you want something, go get it.', '#f2d633', 48, array['"Don’t ever let somebody tell you you can’t" Chris Gardner The Pursuit of Happyness (2006)', 'The Pursuit of Happyness (2006) Chris Gardner character analysis', 'The Pursuit of Happyness (2006) behind the scenes making of', '"Don’t ever let somebody tell you you can’t" quote origin'], 'Character based on the real Chris Gardner (played by Will Smith); verify the scene.'),
('piglet', 'MOVIES', 'character', 'Piglet', 'Winnie the Pooh', 'The things that make me different are the things that make me.', '#f2d633', 49, array['"The things that make me different are the" Piglet Winnie the Pooh', 'Winnie the Pooh Piglet character analysis', 'Winnie the Pooh behind the scenes making of', '"The things that make me different are the" quote origin'], 'Check whether this line is in A. A. Milne''s books, a Disney film, or is a modern attribution.'),
('jack-sparrow', 'MOVIES', 'character', 'Jack Sparrow', 'Pirates of the Caribbean', 'The problem is not the problem. The problem is your attitude about the problem.', '#f2d633', 50, array['"The problem is not the problem. The problem" Jack Sparrow Pirates of the Caribbean', 'Pirates of the Caribbean Jack Sparrow character analysis', 'Pirates of the Caribbean behind the scenes making of', '"The problem is not the problem. The problem" quote origin'], 'Widely attributed to Jack Sparrow; check whether it appears in any Pirates film. If not, say it is a popular misattribution.'),
('donald-duck', 'MOVIES', 'character', 'Donald Duck', 'DuckTales the Movie (1990)', 'Happiness is the richest thing we will ever own.', '#f2d633', 51, array['"Happiness is the richest thing we will ever" Donald Duck DuckTales the Movie (1990)', 'DuckTales the Movie (1990) Donald Duck character analysis', 'DuckTales the Movie (1990) behind the scenes making of', '"Happiness is the richest thing we will ever" quote origin'], 'Check whether this line is in DuckTales the Movie and who says it.'),
('dumbledore', 'MOVIES', 'character', 'Albus Dumbledore', 'Harry Potter and the Prisoner of Azkaban (2004)', 'Happiness can be found even in the darkest of times, if one only remembers to turn on the light.', '#f2d633', 52, array['"Happiness can be found even in the darkest" Albus Dumbledore Harry Potter and the Prisoner of Azkaban (2004)', 'Harry Potter and the Prisoner of Azkaban (2004) Albus Dumbledore character analysis', 'Harry Potter and the Prisoner of Azkaban (2004) behind the scenes making of', '"Happiness can be found even in the darkest" quote origin'], 'Line from the film adaptation; verify.')
