-- Schmart Cards 2.0 — все 52 карточки (из _Schmart_Cards_2_0.pdf)
-- Запусти после schema.sql. Повторный запуск обновит тексты, не трогая собранные знания.
-- notes = подсказки для проверки (не факты): Exa и Claude проверяют их по источникам.

on conflict (id) do update set
  theme = excluded.theme, kind = excluded.kind, person = excluded.person,
  source_work = excluded.source_work, quote = excluded.quote, color = excluded.color,
  sort_order = excluded.sort_order, exa_queries = excluded.exa_queries, notes = excluded.notes,
  updated_at = now();
